class Simulation:
    def __init__(...):
        ...
    def run(self, days: int) -> Dict[str, Any]:
        if not self.people:
            self.initialize()
        self._days_run = 0
        for day in range(days):
            self.step(day)
            self._days_run += 1
        # Summary metrics
        adoption_series = self.series.get("adoption_rate", [])
        time_to_50 = next((i for i, v in enumerate(adoption_series) if v >= 0.5), None)
        peak_adoption = max(adoption_series) if adoption_series else 0.0
        purchase_conv = sum(self.series.get("daily_sold", [])) / max(1, sum(self.series.get("daily_demand", [])))
        results = {
            "adoption_rate_over_time": adoption_series,
            "time_to_reach_50_percent": time_to_50,
            "peak_adoption_rate": peak_adoption,
            "policy_compliance_rate": statistics.mean(self.series.get("compliance_rate_under_mandate", [0.0])) if self.series.get("compliance_rate_under_mandate") else 0.0,
            "context_specific_adoption": {
                "work": self.series.get("adoption_work", []),
                "public": self.series.get("adoption_public", [])
            },
            "purchase_conversion_rate": purchase_conv,
            "adoption_inequality": statistics.mean(self.series.get("adoption_inequality_gini", [0.0])) if self.series.get("adoption_inequality_gini") else 0.0,
        }
        return results

    def visualize(self) -> None:
        try:
            import matplotlib.pyplot as plt
        except Exception:
            return
        fig, axs = plt.subplots(2, 2, figsize=(10, 8))
        axs[0,0].plot(self.series.get("adoption_rate", [])); axs[0,0].set_title("Adoption Rate")
        axs[0,1].plot(self.series.get("average_price", [])); axs[0,1].set_title("Average Price")
        axs[1,0].plot(self.series.get("adoption_public", []), label="Public")
        axs[1,0].plot(self.series.get("adoption_work", []), label="Work")
        axs[1,0].legend(); axs[1,0].set_title("Context Adoption")
        axs[1,1].plot(self.series.get("compliance_rate_under_mandate", [])); axs[1,1].set_title("Compliance (Mandate)")
        plt.tight_layout(); plt.show()

    def save_results(self, path: str) -> None:
        fieldnames = sorted(self.series.keys())
        rows = []
        T = max(len(v) for v in self.series.values()) if self.series else 0
        for t in range(T):
            row = {k: (self.series[k][t] if t < len(self.series[k]) else "") for k in fieldnames}
            row["day"] = t
            rows.append(row)
        try:
            with open(path, "w", newline="") as f:
                writer = csv.DictWriter(f, fieldnames=["day"] + fieldnames)
                writer.writeheader()
                for r in rows:
                    writer.writerow(r)
        except Exception as e:
            print("Failed to save results:", e)

    def validate(self, num_runs: int = 3, days: int = 60) -> Dict[str, Any]:
        seeds = [self.rng.randrange(1_000_000) for _ in range(num_runs)]
        summaries = []
        for s in seeds:
            sim = Simulation(self.p, seed=s)
            res = sim.run(days)
            summaries.append({
                "time_to_50": res.get("time_to_reach_50_percent"),
                "peak": res.get("peak_adoption_rate"),
                "purchase_conversion_rate": res.get("purchase_conversion_rate"),
                "adoption_inequality": res.get("adoption_inequality")
            })
        def safe_mean(vals):
            vals = [v for v in vals if v is not None]
            return statistics.mean(vals) if vals else None
        return {
            "avg_time_to_50": safe_mean([s["time_to_50"] for s in summaries]),
            "avg_peak": safe_mean([s["peak"] for s in summaries]),
            "avg_purchase_conversion_rate": safe_mean([s["purchase_conversion_rate"] for s in summaries]),
            "avg_adoption_inequality": safe_mean([s["adoption_inequality"] for s in summaries])
        }
